        elif n.get('service_mesh'):
            shape_start, shape_end = "(", ")"
        else:
            shape_start, shape_end = "[", "]"

        mermaid_lines.append(f"    {nid}{shape_start}\"{label}\"{shape_end}")
    mermaid_lines.append("  end")

mermaid_lines.append("  classDef mesh fill:#0f172a,stroke:#3b82f6,stroke-width:3px,color:#f8fafc;")
