    nid = n['id']
    if nid in hotspots:
        mermaid_lines.append(f"  class {nid} hotspot;")
    elif n.get('service_mesh'):
        mermaid_lines.append(f"  class {nid} mesh;")
    elif n['type'] == 'infrastructure':
        mermaid_lines.append(f"  class {nid} infra;")
    elif n['type'] == 'observability' or n['type'] == 'service_mesh_control':
