    conn_type = e['connection_type']
    protocol = e['protocol']
    proxied = e['proxied']

    if conn_type == 'async':
        link = f"-. \"{protocol}\" .->"
    else:
        link = f"-- \"{protocol}\" -->"

    mermaid_lines.append(f"  {src} {link} {tgt}")

for i, e in enumerate(edges):
    if e['proxied']:
        mermaid_lines.append(f"  linkStyle {i} stroke:#3b82f6,stroke-width:2px;")
    elif e['connection_type'] == 'async':
